/*
  hlolli_wg_piano - one concert grand for Csound.

  The note voice sums stable damped resonances fitted to piano recordings.
  Strike velocity changes their excitation and damping. Key release damps the strings
  and leaves a small residual ring; handled notes also feed shared body and
  sympathetic resonances. The coefficients describe recorded output, not
  measured string counts or isolated soundboard motion.

  The shared body follows reduced piano models discussed by Balazs Bank and
  Juliette Chabassier in "Model-based digital pianos: from physics to sound
  synthesis" (2018). All runtime data lives in this source. The module plays
  no samples and loads no external data files, in native or WASI builds.

  Source: https://github.com/hlolli/hlolli_wg_piano
  SPDX-License-Identifier: MIT
*/

#include <csdl.h>

#include <math.h>
#include <stdint.h>
#include <string.h>

#define WG_STRINGS 3
#define BODY_LINES 4
#define FELT_MODES 3
#define RESONANCE_BODY_LINES 8
#define WG_MAX_BODY_MODES 64
#define WG_MAX_KEYS 97
#define WG_SYMPATHETIC_PARTIALS 3U
#define WG_SEND_LANES 8U
#define WG_MAX_SYMPATHETIC_MODES \
  (WG_MAX_KEYS * WG_SYMPATHETIC_PARTIALS)
#define WG_PROFILE_SCHEMA_VERSION 4U
#define WG_RADIATION_BANDS 6U

#define WG_PIANO_MANAGER_NAME "::hlolli_wg_piano::manager_v7::"

#define WG_PI 3.14159265358979323846264338327950288
#define WG_TWO_PI 6.28318530717958647692528676655900576
#define WG_LN_1000 6.90775527898213705205397436405309262
/* Unit-RMS coupling rows use this trim before the shared body modes. */
#define WG_BODY_COUPLING_TRIM 0.60

/* Csound's single-threaded WASI build supplies no-op mutex functions and
   returns NULL from Create_Mutex. Native builds need real locks. */
#if defined(__wasi__)
#define WG_REQUIRE_MUTEXES 0
#else
#define WG_REQUIRE_MUTEXES 1
#endif



typedef struct {
  double *data;
  uint32_t size;
  uint32_t write_index;
  double lowpass;
} BODY_LINE;

typedef struct {
  double tuning_cents;
  double inharmonicity_b;
  double loss_rate_per_second;
  double loss_slope_per_second;
  double bridge_loss_per_second;
  double second_string_level;
  double third_string_level;
  double unison_width_cents;
  double hammer_gain;
  double hammer_velocity_hardness;
  double hammer_contact_min_seconds;
  double hammer_contact_range_seconds;
  double hammer_cutoff_base_hz;
  double hammer_cutoff_hardness_hz;
  double hammer_filter_mix;
  double hammer_string_gain;
  double felt_frequency_scale;
  double felt_gain;
  double damper_presence;
  double damper_closed_t60_seconds;
  double damper_lift_start;
  double damper_lift_end;
  double sympathetic_open_t60_seconds;
  double sympathetic_second_level;
  double sympathetic_third_level;
  double radiation_scale;
  double sympathetic_scale;
} WG_KEY_PROFILE;

typedef struct {
  double strike_seconds;
  double strike_error_depth;
  double detune_spread;
  double drift_sign;
  double loss_scale;
  double pan;
} WG_STRING_PROFILE;

typedef struct {
  double frequency_hz;
  double t60_seconds;
  double weight;
} WG_FELT_MODE_PROFILE;

typedef struct {
  double delay_seconds;
  double injection;
} WG_NOTE_BODY_LINE_PROFILE;

typedef struct {
  double frequency_hz;
  double t60_seconds;
  double gain;
  double input_side;
  double stereo_position;
} WG_BODY_MODE_PROFILE;

typedef struct {
  double delay_seconds;
  double input_side;
  double injection;
  double tone_scale;
} WG_FDN_LINE_PROFILE;

typedef struct {
  double key_action_gain;
  double damper_noise_gain;
  double pedal_mechanical_gain;
} WG_MECHANICAL_PROFILE;

typedef struct {
  uint32_t schema_version;
  int32_t midi_min;
  uint32_t key_count;
  uint32_t sympathetic_mode_count;
  uint32_t body_mode_count;
  uint32_t fdn_line_count;
  uint32_t variation_seed;
  WG_KEY_PROFILE default_key;
  const WG_KEY_PROFILE *keys;
  WG_STRING_PROFILE strings[WG_STRINGS];
  WG_FELT_MODE_PROFILE felt_modes[FELT_MODES];
  WG_NOTE_BODY_LINE_PROFILE note_body_lines[BODY_LINES];
  const WG_BODY_MODE_PROFILE *body_modes;
  const double *body_coupling;
  double radiation_centres[WG_RADIATION_BANDS];
  double radiation_q;
  const double *radiation_eq;
  WG_MECHANICAL_PROFILE mechanics;
  WG_FDN_LINE_PROFILE fdn_lines[RESONANCE_BODY_LINES];
} WG_PIANO_PROFILE;

